                                </svg>
                                ${session.project || 'Unknown project'}
                            </span>
                        </div>
                    </a>
                `).join('');

            } catch (error) {
                console.error('Error loading sessions:', error);
                container.innerHTML = '<div class="error">Error loading sessions. Please try again later.</div>';
