        </main>
    </div>

    <script>
        // Configure marked for better rendering
        marked.setOptions({
            gfm: true,
            breaks: true
        });

        async function loadSession() {
            const params = new URLSearchParams(window.location.search);
            const file = params.get('file');

            if (!file) {
                showError('No session file specified');
                return;
            }

            const container = document.getElementById('messages-container');
            const titleEl = document.getElementById('session-title');
            const infoEl = document.getElementById('session-info');

            try {
                const response = await fetch(file);
                if (!response.ok) throw new Error('Failed to load session');

                const text = await response.text();
                const lines = text.trim().split('\n');
                const messages = lines.map(line => JSON.parse(line));

                // Find first user message for title
                const firstUserMsg = messages.find(m => m.type === 'human');
                if (firstUserMsg) {
                    const title = extractTextContent(firstUserMsg.message?.content).substring(0, 100);
                    titleEl.textContent = title + (title.length >= 100 ? '...' : '');
                    document.title = title + ' - Claude Code Sessions';
                }

                infoEl.textContent = `${messages.length} messages`;

                container.innerHTML = messages.map(msg => renderMessage(msg)).join('');

                // Add click handlers for tool toggles
                document.querySelectorAll('.tool-toggle-header').forEach(header => {
                    header.addEventListener('click', () => {
                        header.parentElement.classList.toggle('expanded');
                    });
                });

            } catch (error) {
                console.error('Error loading session:', error);
                showError('Error loading session: ' + error.message);
            }
        }

        function renderMessage(msg) {
            const type = msg.type;
            let role = 'system';
            let content = '';

            if (type === 'human') {
                role = 'user';
                content = renderContent(msg.message?.content);
            } else if (type === 'assistant') {
                role = 'assistant';
                content = renderContent(msg.message?.content);
            } else if (type === 'tool_result') {
                role = 'tool';
                content = renderToolResult(msg);
            } else {
                content = `<pre>${escapeHtml(JSON.stringify(msg, null, 2))}</pre>`;
            }

            const timestamp = msg.timestamp ? formatTime(msg.timestamp) : '';

            return `
                <div class="message ${role}">
                    <div class="message-header">
                        <span class="message-role">${role}</span>
                        ${timestamp ? `<span class="message-time">${timestamp}</span>` : ''}
                    </div>
                    <div class="message-content">${content}</div>
                </div>
            `;
        }

        function renderContent(content) {
            if (!content) return '<em>No content</em>';

            if (typeof content === 'string') {
                return renderMarkdown(content);
            }

            if (Array.isArray(content)) {
                return content.map(block => {
                    if (block.type === 'text') {
                        return `<div class="content-block">${renderMarkdown(block.text)}</div>`;
                    } else if (block.type === 'tool_use') {
                        return renderToolUse(block);
                    } else if (block.type === 'tool_result') {
                        return renderToolResultBlock(block);
                    } else {
                        return `<div class="content-block"><pre>${escapeHtml(JSON.stringify(block, null, 2))}</pre></div>`;
                    }
                }).join('');
            }

            return `<pre>${escapeHtml(JSON.stringify(content, null, 2))}</pre>`;
        }

        function renderMarkdown(text) {
            if (!text) return '';
            return marked.parse(text);
        }

        function renderToolUse(block) {
            const toolName = block.name || 'Unknown Tool';
            const params = block.input || {};

            let paramsHtml = '';
            for (const [key, value] of Object.entries(params)) {
                const displayValue = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
                paramsHtml += `
                    <div class="tool-param">
                        <div class="tool-param-name">${escapeHtml(key)}</div>
                        <div class="tool-param-value">${escapeHtml(displayValue)}</div>
                    </div>
                `;
            }

            return `
                <div class="tool-toggle content-block">
                    <div class="tool-toggle-header">
                        <span class="tool-toggle-title">
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>
                            </svg>
                            ${escapeHtml(toolName)}
                        </span>
